def _render_catalog_page_legacy(active_bots: list[BotCatalogItem], archived_bots: list[BotCatalogItem] | None = None) -> HTMLResponse:

    def render_cards(bots: list[BotCatalogItem], *, archived: bool) -> str:
        if not bots:
            return '<p class="muted empty-state">Nenhuma estratégia nesta seção.</p>'
        badge = '<span class="status-badge">Arquivada</span>' if archived else '<span class="status-badge active">Ativa</span>'
        action = "Ver histórico →" if archived else "Ver resultados →"
        return "".join(
            f'''<a class="bot card" href="/bots/{escape(bot.id)}"><div class="card-meta"><p class="muted">{escape(bot.symbol)} · {escape(bot.timeframe)}</p>{badge}</div><h2>{escape(bot.name)}</h2><p class="muted">{escape(bot.description)}</p><strong>{action}</strong></a>'''
            for bot in bots
        )

    active_cards = render_cards(active_bots, archived=False)
    return _page("Live Core | Estratégias ativas", f"""<main><header class="header"><div><a class="brand" href="/overview" aria-label="Live Core"><img src="/static/brand/logo-1-white-no-bg.png" alt="Live Core"></a><p class="eyebrow">Live Core · XAUUSD</p><h1>Estratégias ativas</h1><p class="muted">Acompanhe os três componentes selecionados e o portfólio coordenador.</p></div><div class="header-actions"><a href="/operations">Saúde operacional</a><form method="post" action="/logout"><button class="link-button" type="submit">Sair</button></form></div></header>
    <section>
      <section class="panel equity-panel"><div class="equity-heading"><div><p class="eyebrow">Mercado e Live Core</p><h2>XAU/USD com desempenho das estratégias</h2><p class="muted">Candles no painel superior · PnL acumulado no painel inferior</p></div><p class="muted" id="equity-status" aria-live="polite">Carregando gráfico...</p></div><div class="chart-toolbar"><div class="chart-options" aria-label="Duração dos candles"><button data-resolution="1m">1m</button><button data-resolution="5m" class="selected">5m</button><button data-resolution="1h">1h</button><button data-resolution="1d">1d</button></div><div class="chart-options" aria-label="Período exibido"><button data-days="7">7D</button><button data-days="30" class="selected">30D</button><button data-days="90">90D</button><button data-days="365">1A</button></div><button id="chart-fit" type="button">Ajustar</button></div><div id="equity-empty" class="muted" hidden></div><div id="equity-chart" role="img" aria-label="Candles XAUUSD e desempenho acumulado das estratégias"></div><div id="equity-legend" class="equity-legend" aria-live="polite"></div><p class="chart-help muted">Arraste para navegar · scroll ou pinça para zoom · arraste o separador entre preço e desempenho</p></section>
      <div class="section-heading"><div><p class="eyebrow">Escopo isolado</p><h2>Estratégias selecionadas</h2></div><p class="muted">{len(active_bots)} estratégias · 3 componentes · 1 coordenador</p></div><section class="grid">{active_cards}</section>
    </section></main><style>
    .header-actions {{ display:flex; gap:16px; align-items:center; }} .header-actions a {{ color:var(--text); }} .catalog-tabs {{ display:inline-flex; gap:4px; padding:4px; margin-bottom:22px; border:1px solid var(--border); border-radius:10px; background:var(--panel); }} .catalog-tabs button {{ display:flex; align-items:center; gap:9px; border:0; border-radius:7px; padding:10px 16px; background:transparent; color:var(--muted); font-weight:700; }} .catalog-tabs button[aria-selected="true"] {{ background:#fff; color:#000; }} .catalog-tabs span {{ min-width:22px; padding:2px 6px; border-radius:999px; background:rgba(127,127,127,.2); font-size:12px; text-align:center; }}
    .equity-panel {{ padding:20px; margin-bottom:28px; overflow:hidden; }} .equity-heading,.section-heading {{ display:flex; align-items:flex-start; justify-content:space-between; gap:18px; }} .equity-heading h2 {{ margin-bottom:6px; }} .equity-heading #equity-status {{ margin:0; text-align:right; }} .chart-toolbar {{ display:flex; align-items:center; flex-wrap:wrap; gap:10px; margin-top:16px; }} .chart-options {{ display:flex; padding:3px; border:1px solid rgba(148,163,184,.18); border-radius:8px; background:#080b10; }} .chart-options button,#chart-fit {{ padding:7px 10px; border:0; border-radius:6px; color:var(--muted); background:transparent; font-weight:700; }} .chart-options button.selected {{ color:#fff; background:rgba(139,124,255,.28); }} #chart-fit {{ margin-left:auto; border:1px solid rgba(148,163,184,.18); }} .eyebrow {{ margin-bottom:6px; color:var(--green); font-size:12px; font-weight:800; letter-spacing:.08em; text-transform:uppercase; }} #equity-chart {{ width:100%; height:540px; margin-top:10px; border:1px solid rgba(148,163,184,.12); border-radius:8px; overflow:hidden; background:#0b0f16; }} .equity-legend {{ min-height:42px; display:flex; align-items:center; flex-wrap:wrap; gap:9px 16px; padding:10px 2px 0; border-top:1px solid rgba(255,255,255,.14); }} .equity-legend time,.equity-legend .ohlc {{ color:#dce4f1; font-size:12px; }} .legend-item {{ display:inline-flex; align-items:center; gap:7px; color:var(--muted); font-size:12px; }} .legend-item strong,.ohlc strong {{ color:var(--text); }} .legend-item i {{ width:18px; height:3px; border-radius:999px; }} .chart-help {{ margin:8px 0 0; font-size:11px; }} .section-heading {{ margin-bottom:14px; }} .section-heading h2 {{ margin-bottom:0; }}
    .grid {{ display:grid; grid-template-columns:repeat(auto-fit,minmax(260px,1fr)); gap:16px; }} .bot {{ min-height:220px; display:flex; flex-direction:column; align-items:flex-start; padding:22px; color:var(--text); text-decoration:none; }} .bot h2,.bot p {{ margin-bottom:12px; }} .bot strong {{ color:var(--green); margin-top:auto; }} .card-meta {{ width:100%; display:flex; justify-content:space-between; gap:12px; align-items:flex-start; }} .status-badge {{ padding:4px 8px; border:1px solid #555; border-radius:999px; color:var(--muted); font-size:11px; font-weight:800; text-transform:uppercase; letter-spacing:.05em; }} .status-badge.active {{ color:var(--green); border-color:rgba(65,211,146,.45); }} .archive-note {{ padding:22px; margin-bottom:18px; border-left:3px solid var(--yellow); }} .archive-note .eyebrow {{ color:var(--yellow); }} .archive-note p:last-child {{ max-width:820px; margin-bottom:0; line-height:1.55; }} .empty-state {{ grid-column:1/-1; padding:24px 0; }}
    @media(max-width:720px) {{ .equity-heading,.section-heading {{ flex-direction:column; }} .equity-heading #equity-status {{ text-align:left; }} #chart-fit {{ margin-left:0; }} #equity-chart {{ height:460px; }} }}
    </style><script src="/static/vendor/lightweight-charts/lightweight-charts.standalone.production.js"></script><script src="/static/equity-chart.js"></script><script>
    const equityChart=LotusEquityChart.create(document.getElementById('equity-chart'),document.getElementById('equity-legend'));
    let chartResolution='5m',chartDays=30,chartRequestSequence=0,chartAbortController=null;
    function renderEquity(data) {{
      const host=document.getElementById('equity-chart'),empty=document.getElementById('equity-empty'),legend=document.getElementById('equity-legend');
      const hasCandles=(data.candles||[]).length>0,hasCurves=(data.series||[]).some(item=>item.points&&item.points.length);
      if(!hasCandles&&!hasCurves) {{ host.hidden=true;empty.hidden=false;empty.textContent='O histórico de mercado e o backtest ainda não foram carregados para este ativo.';legend.innerHTML='';return; }}
      host.hidden=false;empty.hidden=true;equityChart.setData(data);
    }}
    async function loadActiveEquity() {{
      const requestSequence=++chartRequestSequence;
      if(chartAbortController) chartAbortController.abort();
      chartAbortController=new AbortController();
      document.getElementById('equity-status').textContent='Carregando mercado e estratégias...';
      try {{
        const response=await fetch('/api/backtest-market-chart?symbol=XAUUSD&resolution='+chartResolution+'&days='+chartDays,{{signal:chartAbortController.signal}});
        if(response.status===401){{window.location.assign('/login');return;}}
        if(!response.ok)throw new Error('Não foi possível carregar o mercado e os backtests.');
        const data=await response.json();
        if(requestSequence!==chartRequestSequence)return;
        const trades=data.series.reduce((total,item)=>total+item.summary.trades_count,0);
        renderEquity(data);
        document.getElementById('equity-status').textContent=data.candles.length+' candles · '+data.series.length+' curvas'+(trades?' · '+trades+' trades':' · nenhum trade no período')+(data.missing_bot_ids.length?' · '+data.missing_bot_ids.length+' pendentes':'');
      }} catch(error) {{
        if(error.name==='AbortError'||requestSequence!==chartRequestSequence)return;
        document.getElementById('equity-status').textContent=error.message;
      }}
    }}
    document.querySelectorAll('[data-resolution]').forEach(button=>button.onclick=()=>{{document.querySelectorAll('[data-resolution]').forEach(item=>item.classList.remove('selected'));button.classList.add('selected');chartResolution=button.dataset.resolution;loadActiveEquity();}});
    document.querySelectorAll('[data-days]').forEach(button=>button.onclick=()=>{{document.querySelectorAll('[data-days]').forEach(item=>item.classList.remove('selected'));button.classList.add('selected');chartDays=Number(button.dataset.days);loadActiveEquity();}});
    document.getElementById('chart-fit').onclick=()=>equityChart.fitContent();
    loadActiveEquity();
    </script>""")


def render_catalog_page(active_bots: list[BotCatalogItem], archived_bots: list[BotCatalogItem] | None = None) -> HTMLResponse:
    grouped = {family_id: [] for family_id, _, _ in STRATEGY_FAMILIES}
    for bot in active_bots:
        grouped[_strategy_family(bot)].append(bot)

    columns = []
    for family_id, title, description in STRATEGY_FAMILIES:
        bots = sorted(grouped[family_id], key=_family_order)
        cards = "".join(
            f'''<div class="strategy-card-row card"><a class="bot" href="/bots/{escape(bot.id)}"><div class="card-meta"><span class="variant-label">Estratégia ativa</span><span class="status-badge active">Ativa</span></div><p class="market muted">{escape(bot.symbol)} · {escape(bot.timeframe)}</p><div class="strategy-title-block"><h3>{escape(bot.name)}</h3></div><p class="strategy-summary muted">{escape(bot.description)}</p><strong class="results-link">Ver resultados →</strong></a><button class="strategy-card-toggle" type="button" data-chart-bot="{escape(bot.id)}" data-chart-family="{family_id}" aria-pressed="false" aria-label="Exibir {escape(bot.name)} no gráfico"><span class="strategy-card-swatch" aria-hidden="true"></span><span class="strategy-card-toggle-label">Exibir no gráfico</span></button></div>'''
            for bot in bots
        ) or '<div class="family-empty"><p class="muted">Nenhuma estratégia ativa.</p></div>'
        columns.append(
            f'''<article class="strategy-family" data-family="{family_id}"><header class="family-heading"><p class="eyebrow">{len(bots)} {"estratégia" if len(bots) == 1 else "estratégias"}</p><h2>{escape(title)}</h2><p class="muted">{escape(description)}</p><div class="family-chart-actions"><button type="button" data-chart-family-toggle="{family_id}" aria-pressed="false">Ativar categoria</button><button type="button" data-chart-family-only="{family_id}">Somente esta</button></div></header><div class="variant-stack">{cards}</div></article>'''
        )

    return _page("Live Core | Estratégias ativas", f'''<main><header class="header"><div><a class="brand" href="/overview" aria-label="Live Core"><img src="/static/brand/logo-1-white-no-bg.png" alt="Live Core"></a><p class="eyebrow">Live Core · XAUUSD</p><h1>Estratégias ativas</h1><p class="muted">Acompanhe os três componentes selecionados e o portfólio coordenador.</p></div><div class="header-actions"><a href="/operations">Saúde operacional</a><form method="post" action="/logout"><button class="link-button" type="submit">Sair</button></form></div></header>
    <section>
      <section class="panel equity-panel"><div class="equity-heading"><div><p class="eyebrow">Mercado e Live Core</p><h2>XAU/USD com desempenho das estratégias</h2><p class="muted">Candles no painel superior · PnL acumulado no painel inferior</p></div><p class="muted" id="equity-status" aria-live="polite">Carregando gráfico...</p></div><div class="chart-toolbar"><div class="chart-options" aria-label="Modo de risco"><button class="selected">1% Risk/Trade</button></div><div class="chart-options" aria-label="Duração dos candles"><button data-resolution="1m">1m</button><button data-resolution="5m">5m</button><button data-resolution="1h">1h</button><button data-resolution="1d" class="selected">1d</button></div><div class="chart-options" aria-label="Período exibido"><button data-days="7">7D</button><button data-days="30">30D</button><button data-days="90">90D</button><button data-days="365" class="selected">1A</button></div><button id="chart-fit" type="button">Ajustar</button></div><p id="strategy-filter-hint" class="strategy-filter-hint" role="status" aria-live="polite"></p><div id="equity-empty" class="muted" hidden></div><div id="equity-chart" role="img" aria-label="Candles XAUUSD e desempenho acumulado das estratégias"></div><div id="equity-legend" class="equity-legend" aria-live="polite"></div><p class="chart-help muted">Cada período reinicia em US$ 10.000 e simula risco de 1% por entrada na janela selecionada.</p></section>
      <div class="section-heading"><div><p class="eyebrow">Em operação protegida</p><h2>Famílias de estratégias</h2><p class="muted">A mesma organização visual do Research Workspace, limitada aos perfis promovidos.</p></div><p class="muted">{len(active_bots)} estratégias ativas</p></div><section class="family-grid">{"".join(columns)}</section>
    </section></main><style>
    .header-actions{{display:flex;gap:16px;align-items:center}}.header-actions a{{color:var(--text)}}
    .equity-panel{{padding:20px;margin-bottom:28px;overflow:hidden}}.equity-heading,.section-heading{{display:flex;align-items:flex-start;justify-content:space-between;gap:18px}}.equity-heading h2{{margin-bottom:6px}}.equity-heading>p{{margin:0;text-align:right}}.chart-toolbar{{display:flex;align-items:center;flex-wrap:wrap;gap:10px;margin-top:16px}}.chart-options{{display:flex;padding:3px;border:1px solid rgba(148,163,184,.18);border-radius:8px;background:#080b10}}.chart-options button,#chart-fit{{padding:7px 10px;border:0;border-radius:6px;color:var(--muted);background:transparent;font-weight:700}}.chart-options button.selected{{color:#fff;background:rgba(139,124,255,.28)}}#chart-fit{{margin-left:auto;border:1px solid rgba(148,163,184,.18)}}.strategy-filter-hint{{min-height:16px;margin:8px 0 0;color:var(--yellow);font-size:11px}}.eyebrow{{margin-bottom:6px;color:var(--green);font-size:12px;font-weight:800;letter-spacing:.08em;text-transform:uppercase}}#equity-chart{{width:100%;height:540px;margin-top:10px;border:1px solid rgba(148,163,184,.12);border-radius:8px;overflow:hidden;background:#0b0f16}}.equity-legend{{min-height:42px;display:flex;align-items:center;flex-wrap:wrap;gap:9px 16px;padding:10px 2px 0;border-top:1px solid rgba(255,255,255,.14)}}.equity-legend time,.equity-legend .ohlc{{color:#dce4f1;font-size:12px}}.legend-item{{display:inline-flex;align-items:center;gap:7px;color:var(--muted);font-size:12px}}.legend-item strong,.ohlc strong{{color:var(--text)}}.legend-item i{{width:18px;height:3px;border-radius:999px}}.chart-help{{margin:8px 0 0;font-size:11px}}.section-heading{{margin-bottom:14px}}.section-heading h2{{margin-bottom:0}}
    .family-grid{{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px;align-items:start}}.strategy-family{{min-width:0}}.family-heading{{height:220px;min-height:220px;padding:18px;border:1px solid var(--border);border-bottom:0;border-radius:10px 10px 0 0;background:var(--panel2)}}.family-heading h2{{margin-bottom:9px;font-size:20px}}.family-heading>p:last-of-type{{margin-bottom:0;font-size:13px;line-height:1.45}}.family-chart-actions{{display:flex;flex-wrap:nowrap;gap:6px;margin-top:13px}}.family-chart-actions button{{flex:0 0 108px;width:108px;height:32px;padding:0 6px;border:1px solid rgba(148,163,184,.35);border-radius:6px;color:var(--muted);background:#090c12;font-size:11px;font-weight:700;white-space:nowrap}}.family-chart-actions button[aria-pressed="true"]{{color:#000;border-color:var(--green);background:var(--green)}}.variant-stack{{display:flex;flex-direction:column;gap:12px;padding:12px;border:1px solid var(--border);border-radius:0 0 10px 10px;background:rgba(255,255,255,.025)}}.strategy-card-row{{display:flex;height:330px;min-height:330px;flex-direction:column;overflow:hidden}}.strategy-card-row .bot{{flex:0 0 286px;min-height:286px;display:flex;flex-direction:column;align-items:stretch;padding:17px 16px 10px;color:var(--text);text-decoration:none}}.bot h3,.bot p{{margin-bottom:0}}.strategy-title-block{{min-height:45px;margin-bottom:10px}}.bot h3{{margin:0;font-size:17px;line-height:1.25}}.bot .strategy-summary{{display:-webkit-box;overflow:hidden;margin:0;font-size:13px;line-height:1.45;-webkit-box-orient:vertical;-webkit-line-clamp:4}}.bot .results-link{{display:block;width:100%;margin-top:auto;padding-top:12px;border-top:1px solid rgba(148,163,184,.16);color:var(--green)}}.bot .market{{margin:11px 0 8px;font-size:12px}}.card-meta{{width:100%;display:flex;justify-content:space-between;gap:8px;align-items:center}}.variant-label{{color:var(--yellow);font-size:11px;font-weight:800;letter-spacing:.04em;text-transform:uppercase}}.status-badge{{padding:4px 8px;border:1px solid #555;border-radius:999px;color:var(--muted);font-size:11px;font-weight:800;text-transform:uppercase;letter-spacing:.05em}}.status-badge.active{{color:var(--green);border-color:rgba(65,211,146,.45)}}.family-empty{{min-height:112px;display:grid;place-items:center;padding:18px;border:1px dashed rgba(166,166,166,.35);border-radius:8px;text-align:center}}.strategy-card-toggle{{display:flex;align-items:center;justify-content:center;gap:8px;margin:0 12px 12px;padding:9px 12px;border:1px solid rgba(148,163,184,.28);border-radius:7px;color:var(--muted);background:#0c1017;font-size:11px;font-weight:700}}.strategy-card-toggle[aria-pressed="true"]{{color:#fff;border-color:var(--strategy-color);background:#15221d}}.strategy-card-swatch{{width:11px;height:11px;border-radius:50%;background:var(--strategy-color,#555)}}.strategy-card-toggle:disabled,.family-chart-actions button:disabled{{cursor:not-allowed;opacity:.35}}
    @media(max-width:1040px){{.family-grid{{grid-template-columns:repeat(2,minmax(0,1fr))}}}}@media(max-width:720px){{.equity-heading,.section-heading{{flex-direction:column}}.equity-heading>p{{text-align:left}}#chart-fit{{margin-left:0}}#equity-chart{{height:460px}}.family-grid{{grid-template-columns:1fr}}.family-heading{{height:auto;min-height:auto}}}}
    </style><script src="/static/vendor/lightweight-charts/lightweight-charts.standalone.production.js"></script><script src="/static/equity-chart.js?v=2"></script><script>
    const equityChart=LotusEquityChart.create(document.getElementById('equity-chart'),document.getElementById('equity-legend'));
    const storageKey='live-core:equity-visible-strategies:v1';let chartResolution='1d',chartDays=365,currentData=null,selectedBotIds=null,hintTimer=null;
    function family(profile){{const value=(profile||'').toLowerCase();if(value.includes('portfolio'))return'combined';if(value.includes('zigzag'))return'zigzag';if(value.includes('stochastic'))return'stochastic';if(value.includes('multitimeframe'))return'multitimeframe';return'combined'}}
    function reconcile(series){{const available=new Set(series.map(item=>item.bot_id));if(selectedBotIds===null){{try{{selectedBotIds=new Set(JSON.parse(localStorage.getItem(storageKey)||'[]'))}}catch(error){{selectedBotIds=new Set()}}}}selectedBotIds=new Set([...selectedBotIds].filter(id=>available.has(id)));if(!selectedBotIds.size)series.forEach(item=>selectedBotIds.add(item.bot_id));save()}}
    function save(){{try{{localStorage.setItem(storageKey,JSON.stringify([...selectedBotIds]))}}catch(error){{}}}}
    function hint(message){{const node=document.getElementById('strategy-filter-hint');node.textContent=message;clearTimeout(hintTimer);hintTimer=setTimeout(()=>node.textContent='',2400)}}
    function sync(){{const state=equityChart.getSeriesState(),byId=new Map(state.map(item=>[item.botId,item]));document.querySelectorAll('[data-chart-bot]').forEach(button=>{{const item=byId.get(button.dataset.chartBot),visible=Boolean(item&&item.visible);button.disabled=!item;button.setAttribute('aria-pressed',String(visible));button.querySelector('.strategy-card-toggle-label').textContent=visible?'No gráfico':'Exibir no gráfico';if(item)button.style.setProperty('--strategy-color',item.color)}});document.querySelectorAll('[data-chart-family-toggle]').forEach(button=>{{const ids=state.filter(item=>family(item.strategyProfile)===button.dataset.chartFamilyToggle).map(item=>item.botId),active=ids.length&&ids.every(id=>selectedBotIds.has(id));button.disabled=!ids.length;button.setAttribute('aria-pressed',String(active));button.textContent=active?'Desativar':'Ativar categoria'}});document.querySelectorAll('[data-chart-family-only]').forEach(button=>button.disabled=!state.some(item=>family(item.strategyProfile)===button.dataset.chartFamilyOnly))}}
    function status(){{if(!currentData)return;const visible=(currentData.series||[]).filter(item=>selectedBotIds.has(item.bot_id)),trades=visible.reduce((total,item)=>total+Number(item.summary&&item.summary.trades_count||0),0);document.getElementById('equity-status').textContent=(currentData.candles||[]).length+' candles · '+visible.length+' de '+(currentData.series||[]).length+' curvas'+(trades?' · '+trades+' trades':'')}}
    function apply(){{equityChart.setVisibleBotIds(selectedBotIds);sync();status();save()}}
    function toggle(id){{if(selectedBotIds.has(id)&&selectedBotIds.size===1)return hint('Pelo menos uma estratégia deve permanecer visível.');selectedBotIds.has(id)?selectedBotIds.delete(id):selectedBotIds.add(id);apply()}}
    function toggleFamily(id){{const ids=equityChart.getSeriesState().filter(item=>family(item.strategyProfile)===id).map(item=>item.botId),active=ids.length&&ids.every(botId=>selectedBotIds.has(botId));if(active&&selectedBotIds.size===ids.length)return hint('Pelo menos uma categoria deve permanecer visível.');ids.forEach(botId=>active?selectedBotIds.delete(botId):selectedBotIds.add(botId));apply()}}
    function isolate(id){{selectedBotIds=new Set(equityChart.getSeriesState().filter(item=>family(item.strategyProfile)===id).map(item=>item.botId));if(selectedBotIds.size)apply()}}
    async function load(){{document.getElementById('equity-status').textContent='Carregando mercado e estratégias...';try{{const response=await fetch('/api/backtest-market-chart?symbol=XAUUSD&resolution='+chartResolution+'&days='+chartDays);if(!response.ok)throw Error('Não foi possível carregar o mercado e os backtests.');currentData=await response.json();const drawable=(currentData.series||[]).filter(item=>item.points&&item.points.length);reconcile(drawable);const hasData=(currentData.candles||[]).length||drawable.length,host=document.getElementById('equity-chart'),empty=document.getElementById('equity-empty');host.hidden=!hasData;empty.hidden=Boolean(hasData);if(!hasData){{empty.textContent='O histórico de mercado e o backtest ainda não foram carregados.';return}}equityChart.setData(currentData,{{visibleBotIds:selectedBotIds}});sync();status()}}catch(error){{document.getElementById('equity-status').textContent=error.message}}}}
    document.querySelectorAll('[data-chart-bot]').forEach(button=>button.onclick=()=>toggle(button.dataset.chartBot));document.querySelectorAll('[data-chart-family-toggle]').forEach(button=>button.onclick=()=>toggleFamily(button.dataset.chartFamilyToggle));document.querySelectorAll('[data-chart-family-only]').forEach(button=>button.onclick=()=>isolate(button.dataset.chartFamilyOnly));document.querySelectorAll('[data-resolution]').forEach(button=>button.onclick=()=>{{document.querySelectorAll('[data-resolution]').forEach(item=>item.classList.remove('selected'));button.classList.add('selected');chartResolution=button.dataset.resolution;load()}});document.querySelectorAll('[data-days]').forEach(button=>button.onclick=()=>{{document.querySelectorAll('[data-days]').forEach(item=>item.classList.remove('selected'));button.classList.add('selected');chartDays=Number(button.dataset.days);load()}});document.getElementById('chart-fit').onclick=()=>equityChart.fitContent();load();
    </script>''')


def _render_growth_simulator_page_legacy() -> HTMLResponse:
    return _page("Live Core | Simulador de crescimento", """<main><header class="header"><div><a class="brand brand-compact" href="/bots" aria-label="Live Core"><img src="/static/brand/logo-1-white-no-bg.png" alt="Live Core"></a><p class="eyebrow">Happy Gold + Portfólio 7/6 · 100/100</p><h1>Simulador de crescimento</h1><p class="muted">Reaplique as operações disponíveis no replay anual com capital e risco personalizados.</p></div><div class="actions"><a href="/bots/core-portfolio">Ver estratégia</a><a href="/bots">Estratégias</a><form method="post" action="/logout"><button class="link-button" type="submit">Sair</button></form></div></header>
    <section class="panel controls"><form id="simulation-form"><label>Capital inicial (USD)<input id="initial-balance" name="initial_balance" type="number" min="100" max="100000000" step="100" value="10000" required></label><label>Risco-base por operação (%)<input id="risk" name="risk_per_trade_pct" type="number" min="0.01" max="10" step="0.01" value="0.25" required></label><button type="submit">Simular curva</button></form><p class="muted">O risco é recalculado sobre o saldo antes de cada operação. A sequência de entradas e os resultados em R permanecem iguais ao backtest.</p></section>
    <section class="cards"><article class="card"><p class="muted">Saldo final</p><strong id="final-balance">-</strong><span id="initial-label">-</span></article><article class="card"><p class="muted">PnL projetado</p><strong id="net-pnl">-</strong><span id="return-pct">-</span></article><article class="card"><p class="muted">Drawdown máximo</p><strong id="drawdown">-</strong><span id="drawdown-pct">-</span></article><article class="card"><p class="muted">Operações simuladas</p><strong id="trades">-</strong><span id="period">-</span></article></section>
    <section class="panel chart-panel"><div class="chart-heading"><div><h2>Curva de saldo</h2><p class="muted">Referência: US$ 10.000 e risco de 0,25% · Simulação: valores personalizados</p></div><p class="muted" id="status">Carregando...</p></div><div id="chart-empty" class="muted" hidden></div><svg id="growth-chart" viewBox="0 0 1100 440" role="img" aria-label="Curva simulada de crescimento"></svg><div class="legend"><span><i class="reference"></i>Referência</span><span><i class="simulation"></i>Simulação personalizada</span></div></section>
    <section class="panel warning"><strong>Importante</strong><p class="muted">Esta é uma projeção matemática sobre o histórico já observado. Ela não prevê resultados futuros e não considera mudanças de liquidez, slippage ou capacidade operacional causadas por volumes maiores.</p></section></main><style>
    .eyebrow { margin:0 0 7px; color:var(--green); font-size:12px; font-weight:800; letter-spacing:.08em; text-transform:uppercase; } .actions { display:flex; gap:14px; align-items:flex-start; flex-wrap:wrap; } .actions a { color:var(--text); } .controls { padding:20px; margin-bottom:18px; } .controls form { display:grid; grid-template-columns:repeat(2,minmax(180px,260px)) auto; gap:14px; align-items:end; } label { display:grid; gap:7px; color:var(--muted); font-size:13px; font-weight:700; } input { width:100%; padding:11px 12px; color:var(--text); background:#000; border:1px solid var(--border); border-radius:7px; font:inherit; } input:focus { outline:2px solid rgba(65,211,146,.35); border-color:var(--green); } .controls button { padding:11px 18px; border:1px solid #fff; border-radius:7px; color:#000; background:#fff; font-weight:800; } .controls p { margin:14px 0 0; line-height:1.5; } .cards { display:grid; grid-template-columns:repeat(4,minmax(0,1fr)); gap:14px; margin-bottom:18px; } .card { padding:18px; } .card strong { display:block; margin-bottom:8px; font-size:26px; } .card span { color:var(--muted); font-size:13px; } .green { color:var(--green); } .red { color:var(--red); } .chart-panel { padding:20px; margin-bottom:18px; } .chart-heading { display:flex; justify-content:space-between; gap:18px; } .chart-heading h2 { margin-bottom:6px; } #growth-chart { width:100%; min-height:330px; margin-top:8px; } .legend { display:flex; gap:20px; padding-top:12px; border-top:1px solid rgba(255,255,255,.14); color:var(--muted); font-size:13px; } .legend span { display:flex; align-items:center; gap:8px; } .legend i { display:block; width:22px; height:3px; border-radius:999px; } .legend .reference { background:#777; } .legend .simulation { background:var(--green); } .warning { padding:18px; border-left:3px solid var(--yellow); } .warning p { margin:7px 0 0; line-height:1.55; } @media(max-width:850px) { .cards { grid-template-columns:repeat(2,1fr); } .controls form { grid-template-columns:1fr 1fr; } .controls button { grid-column:1/-1; } } @media(max-width:560px) { .cards,.controls form { grid-template-columns:1fr; } .controls button { grid-column:auto; } .chart-heading,.actions { flex-direction:column; } #growth-chart { min-height:260px; } }
    </style><script>
    const money=value=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'USD'}).format(value||0); const pct=value=>new Intl.NumberFormat('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2}).format(value||0)+'%';
    function renderChart(data) { const svg=document.getElementById('growth-chart'), empty=document.getElementById('chart-empty'), series=[{...data.reference,color:'#777'},{...data.simulation,color:'#41d392'}].filter(item=>item.points.length); if(!series.length){svg.hidden=true;empty.hidden=false;empty.textContent='Não há operações para simular.';return;} svg.hidden=false;empty.hidden=true; const W=1100,H=440,L=86,R=22,T=22,B=48; const times=series.flatMap(item=>item.points.map(p=>+new Date(p.day+'T00:00:00Z'))), balances=series.flatMap(item=>item.points.map(p=>+p.balance)); const minX=Math.min(...times),maxX=Math.max(...times),rawMin=Math.min(...balances),rawMax=Math.max(...balances),pad=Math.max((rawMax-rawMin)*.12,100),minY=Math.max(0,rawMin-pad),maxY=rawMax+pad; const x=v=>L+(v-minX)*(W-L-R)/Math.max(maxX-minX,1),y=v=>T+(maxY-v)*(H-T-B)/Math.max(maxY-minY,1); const grid=[0,.25,.5,.75,1].map(r=>{const value=maxY-(maxY-minY)*r,yy=y(value);return `<line x1="${L}" x2="${W-R}" y1="${yy}" y2="${yy}" stroke="#292929"/><text x="${L-9}" y="${yy+4}" text-anchor="end" fill="#999" font-size="11">${money(value)}</text>`}).join(''); const paths=series.map(item=>{const d=item.points.map((p,i)=>`${i?'L':'M'} ${x(+new Date(p.day+'T00:00:00Z')).toFixed(1)} ${y(+p.balance).toFixed(1)}`).join(' '); const last=item.points.at(-1); return `<path d="${d}" fill="none" stroke="${item.color}" stroke-width="${item.label==='Simulação'?4:2}" stroke-linejoin="round"/><circle cx="${x(+new Date(last.day+'T00:00:00Z'))}" cy="${y(+last.balance)}" r="5" fill="${item.color}"><title>${item.label}: ${money(last.balance)}</title></circle>`}).join(''); const labels=`<text x="${L}" y="${H-12}" fill="#999" font-size="11">${new Date(minX).toLocaleDateString('pt-BR')}</text><text x="${W-R}" y="${H-12}" text-anchor="end" fill="#999" font-size="11">${new Date(maxX).toLocaleDateString('pt-BR')}</text>`; svg.innerHTML=grid+paths+labels; }
    function render(data) { const s=data.simulation; document.getElementById('final-balance').textContent=money(s.final_balance); document.getElementById('initial-label').textContent='Capital inicial '+money(s.initial_balance)+' · risco '+pct(s.risk_per_trade_pct); const pnl=document.getElementById('net-pnl'); pnl.textContent=money(s.net_pnl); pnl.className=s.net_pnl>=0?'green':'red'; document.getElementById('return-pct').textContent='Retorno '+pct(s.return_pct); document.getElementById('drawdown').textContent=money(s.max_drawdown); document.getElementById('drawdown-pct').textContent=pct(s.max_drawdown_pct)+' sobre o pico'; document.getElementById('trades').textContent=s.trades_simulated; document.getElementById('period').textContent=new Date(data.period_start_utc).toLocaleDateString('pt-BR')+' a '+new Date(data.period_end_utc).toLocaleDateString('pt-BR'); document.getElementById('status').textContent='Curva atualizada'; renderChart(data); }
    async function simulate(event) { if(event)event.preventDefault(); const form=document.getElementById('simulation-form'),params=new URLSearchParams(new FormData(form)); document.getElementById('status').textContent='Simulando...'; const response=await fetch('/api/growth-simulation?'+params); if(!response.ok){const payload=await response.json().catch(()=>({}));throw new Error(payload.detail||'Não foi possível executar a simulação.');} render(await response.json()); }
    document.getElementById('simulation-form').onsubmit=event=>simulate(event).catch(error=>document.getElementById('status').textContent=error.message); simulate().catch(error=>document.getElementById('status').textContent=error.message);
    </script>""")


def render_growth_simulator_page() -> HTMLResponse:
    return _page("Live Core | Simulador", """<main><header class="header"><div><a class="brand brand-compact" href="/bots"><img src="/static/brand/logo-1-white-no-bg.png" alt="Live Core"></a><p class="eyebrow">Combinação das 3 V3</p><h1>Simulador de crescimento</h1><p class="muted">Reaplique o replay anual disponível com risco composto e reduções permanentes por saldo.</p></div><div class="actions"><a href="/bots/core-combined-v3">Ver combinação</a><a href="/operations">Saúde</a><a href="/bots">Estratégias</a></div></header>
    <section class="panel controls"><form id="simulation-form"><label>Capital inicial (USD)<input id="initial-balance" type="number" min="1" max="100000000" step="1" value="10000" required></label><label>Risco por operação (%)<input id="base-risk" type="number" min="0.01" max="10" step="0.01" value="0.25" required></label><button class="primary" type="submit">Simular curva</button><div class="optional-tiers"><div class="tier-heading"><div><strong>Faixas de redução de risco</strong><small class="muted">Opcional</small></div><button id="add-tier" type="button">+ Adicionar faixa</button></div><div id="tiers"></div></div></form><p class="muted">Se adicionar faixas, o risco menor fica travado ao atingir o capital definido, mesmo que o saldo recue.</p></section>
    <section class="cards"><article class="card"><p class="muted">Saldo final</p><strong id="final-balance">-</strong><span id="minimum-balance">-</span></article><article class="card"><p class="muted">PnL / retorno</p><strong id="net-pnl">-</strong><span id="return-pct">-</span></article><article class="card"><p class="muted">Drawdown máximo</p><strong id="drawdown">-</strong><span id="drawdown-pct">-</span></article><article class="card"><p class="muted">Operações</p><strong id="trades">-</strong><span id="period">-</span></article></section>
    <section class="panel chart-panel"><div class="chart-heading"><div><h2>Curva de saldo</h2><p class="muted">Cenário calculado com o capital e o risco informados.</p></div><p class="muted" id="status">Carregando...</p></div><svg id="growth-chart" viewBox="0 0 1100 440" role="img"></svg><div id="milestones" class="milestones"></div></section>
    <section class="panel warning"><strong>Projeção histórica</strong><p class="muted">Não prevê resultados futuros e não modela lote mínimo, margem ou mudança de execução em volumes maiores.</p></section></main><style>
    .eyebrow{color:var(--green);font-size:12px;font-weight:800;text-transform:uppercase}.actions{display:flex;gap:14px}.actions a{color:var(--text)}.controls,.chart-panel,.warning{padding:20px;margin-bottom:18px}.controls form{display:grid;grid-template-columns:220px 220px auto;gap:18px;align-items:end}label{display:grid;gap:7px;color:var(--muted);font-size:13px}input{padding:10px;color:#fff;background:#000;border:1px solid var(--border);border-radius:7px;font:inherit}.optional-tiers{grid-column:1/-1;padding-top:4px}.tier-heading,.tier-row{display:flex;gap:10px;align-items:center}.tier-heading{justify-content:space-between;margin-bottom:8px}.tier-heading strong,.tier-heading small{display:block}.tier-heading small{margin-top:3px}.tier-row{margin-top:7px}.tier-row input{width:150px}.tier-row button,.tier-heading button{color:var(--muted);background:#000;border:1px solid var(--border);border-radius:6px;padding:8px}.primary{padding:11px 18px;background:#fff;color:#000;border:0;border-radius:7px;font-weight:800}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin-bottom:18px}.card{padding:18px}.card strong{display:block;font-size:25px;margin-bottom:7px}.card span{color:var(--muted);font-size:13px}.chart-heading{display:flex;justify-content:space-between;gap:16px}#growth-chart{width:100%;min-height:330px}.milestones{display:flex;flex-wrap:wrap;gap:8px;border-top:1px solid #333;padding-top:12px}.milestones span{padding:7px 9px;background:#151515;border-radius:6px;color:var(--muted);font-size:12px}.milestones:empty{display:none}.warning{border-left:3px solid var(--yellow)}.warning p{margin:7px 0 0}.green{color:var(--green)}.red{color:var(--red)}@media(max-width:800px){.controls form,.cards{grid-template-columns:1fr 1fr}.primary{grid-column:1/-1}}@media(max-width:560px){.controls form,.cards{grid-template-columns:1fr}.primary{grid-column:auto}.tier-row{flex-wrap:wrap}.chart-heading,.actions{flex-direction:column}}
    </style><script>
    const money=v=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'USD'}).format(v||0),pct=v=>Number(v||0).toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2})+'%';
    function addTier(threshold='',risk=''){const row=document.createElement('div');row.className='tier-row';row.innerHTML=`<input data-field="threshold" type="number" min="0" step="1" value="${threshold}" placeholder="Capital da faixa" aria-label="Saldo da faixa" required><span>USD →</span><input data-field="risk" type="number" min="0.01" max="10" step="0.01" value="${risk}" placeholder="Novo risco" aria-label="Risco da faixa" required><span>%</span><button type="button">Remover</button>`;row.querySelector('button').onclick=()=>row.remove();document.getElementById('tiers').append(row)} document.getElementById('add-tier').onclick=()=>addTier();
    function chart(data){const svg=document.getElementById('growth-chart'),series=data.simulation,W=1100,H=440,L=86,R=20,T=20,B=45,times=series.points.map(p=>+new Date(p.day+'T00:00:00Z')),vals=series.points.map(p=>+p.balance),minX=Math.min(...times),maxX=Math.max(...times),lo=Math.min(...vals),hi=Math.max(...vals),pad=Math.max((hi-lo)*.1,1),minY=Math.max(0,lo-pad),maxY=hi+pad,x=v=>L+(v-minX)*(W-L-R)/Math.max(maxX-minX,1),y=v=>T+(maxY-v)*(H-T-B)/Math.max(maxY-minY,1);const grid=[0,.25,.5,.75,1].map(r=>{const v=maxY-(maxY-minY)*r,yy=y(v);return `<line x1="${L}" x2="${W-R}" y1="${yy}" y2="${yy}" stroke="#292929"/><text x="${L-8}" y="${yy+4}" text-anchor="end" fill="#999" font-size="11">${money(v)}</text>`}).join(''),path=`<path d="${series.points.map((p,i)=>`${i?'L':'M'} ${x(+new Date(p.day+'T00:00:00Z'))} ${y(+p.balance)}`).join(' ')}" fill="none" stroke="#41d392" stroke-width="4"/>`;svg.innerHTML=grid+path}
    function render(data){const s=data.simulation;document.getElementById('final-balance').textContent=money(s.final_balance);document.getElementById('minimum-balance').textContent='Mínimo '+money(s.minimum_balance);const pnl=document.getElementById('net-pnl');pnl.textContent=money(s.net_pnl);pnl.className=s.net_pnl>=0?'green':'red';document.getElementById('return-pct').textContent=pct(s.return_pct);document.getElementById('drawdown').textContent=money(s.max_drawdown);document.getElementById('drawdown-pct').textContent=pct(s.max_drawdown_pct);document.getElementById('trades').textContent=s.trades_simulated;document.getElementById('period').textContent=new Date(data.period_start_utc).toLocaleDateString('pt-BR')+' a '+new Date(data.period_end_utc).toLocaleDateString('pt-BR');document.getElementById('milestones').innerHTML=s.milestones.map(m=>`<span>${money(m.balance_threshold)} · ${pct(m.risk_per_trade_pct)} · ${m.reached_at_utc?new Date(m.reached_at_utc).toLocaleDateString('pt-BR'):'não atingido'}</span>`).join('');document.getElementById('status').textContent='Curva atualizada';chart(data)}
    async function simulate(event){if(event)event.preventDefault();const tiers=[{balance_threshold:0,risk_per_trade_pct:+document.getElementById('base-risk').value},...[...document.querySelectorAll('.tier-row')].map(row=>({balance_threshold:+row.querySelector('[data-field="threshold"]').value,risk_per_trade_pct:+row.querySelector('[data-field="risk"]').value}))];document.getElementById('status').textContent='Simulando...';const response=await fetch('/api/growth-simulation',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({initial_balance:+document.getElementById('initial-balance').value,risk_tiers:tiers})});if(!response.ok){const p=await response.json().catch(()=>({}));throw new Error(p.detail||'Falha na simulação.')}render(await response.json())}document.getElementById('simulation-form').onsubmit=e=>simulate(e).catch(err=>document.getElementById('status').textContent=err.message);simulate().catch(err=>document.getElementById('status').textContent=err.message);
    </script>""")


def render_trades_page() -> HTMLResponse:
    return _page("Live Core | Operações", """<main><header class="header"><div><h1>Operações</h1><p class="muted">Histórico consolidado das estratégias acompanhadas pelo Live Core.</p></div><p class="muted" id="trades-updated">Carregando...</p></header><section class="trade-summary"><article class="panel"><span>Operações encontradas</span><strong id="trade-count">—</strong></article><article class="panel"><span>PnL líquido consolidado</span><strong id="trade-pnl">—</strong></article><article class="panel"><span>Estratégias com registros</span><strong id="trade-strategies">—</strong></article></section><section class="panel trade-panel"><div class="table-wrap"><table><thead><tr><th>Estratégia</th><th>Abertura</th><th>Fechamento</th><th>Lado</th><th>Volume</th><th>Entrada</th><th>Saída</th><th>PnL líquido</th></tr></thead><tbody id="trade-rows"><tr><td colspan="8" class="muted">Carregando operações...</td></tr></tbody></table></div></section></main><style>
    .trade-summary{display:grid;grid-template-columns:repeat(3,1fr);gap:13px;margin-bottom:18px}.trade-summary article{padding:18px}.trade-summary span{color:var(--muted);font-size:12px}.trade-summary strong{display:block;margin-top:12px;font-size:25px}.trade-panel{padding:0;overflow:hidden}.table-wrap{overflow:auto}table{width:100%;min-width:1040px;border-collapse:collapse}th,td{padding:14px 16px;border-bottom:1px solid #222c3b;text-align:left}th{color:var(--muted);font-size:11px;letter-spacing:.06em;text-transform:uppercase}td{font-size:13px}.buy{color:var(--green)}.sell{color:var(--red)}.positive{color:var(--green)}.negative{color:var(--red)}@media(max-width:700px){.trade-summary{grid-template-columns:1fr}}
    </style><script>
    const tradeMoney=value=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'USD'}).format(value||0),tradeDate=value=>value?new Date(value).toLocaleString('pt-BR',{timeZone:'UTC'})+' UTC':'Em aberto';
    fetch('/api/bots').then(response=>{{if(!response.ok)throw Error('Falha ao carregar estratégias.');return response.json()}}).then(async bots=>{{const results=await Promise.all(bots.map(async bot=>{{const response=await fetch('/api/bots/'+encodeURIComponent(bot.id)+'/results');if(!response.ok)throw Error('Falha ao carregar operações de '+bot.name);return {{bot,data:await response.json()}}}}));const trades=results.flatMap(item=>item.data.trades.map(trade=>({{...trade,bot_name:item.bot.name}}))).sort((a,b)=>new Date(b.opened_at_utc)-new Date(a.opened_at_utc));const pnl=trades.reduce((total,trade)=>total+Number(trade.net_pnl||0),0),strategies=new Set(trades.map(trade=>trade.bot_name));document.getElementById('trade-count').textContent=trades.length;const pnlNode=document.getElementById('trade-pnl');pnlNode.textContent=tradeMoney(pnl);pnlNode.className=pnl>=0?'positive':'negative';document.getElementById('trade-strategies').textContent=strategies.size;document.getElementById('trades-updated').textContent='Atualizado agora';document.getElementById('trade-rows').innerHTML=trades.length?trades.map(trade=>`<tr><td><strong>${{escapeHtml(trade.bot_name)}}</strong><br><small class="muted">${{escapeHtml(trade.setup||trade.trade_id)}}</small></td><td>${{tradeDate(trade.opened_at_utc)}}</td><td>${{tradeDate(trade.closed_at_utc)}}</td><td class="${{escapeHtml(trade.side)}}">${{escapeHtml(trade.side)}}</td><td>${{Number(trade.volume_lots||0).toFixed(2)}}</td><td>${{Number(trade.entry_price||0).toFixed(2)}}</td><td>${{trade.exit_price==null?'—':Number(trade.exit_price).toFixed(2)}}</td><td class="${{Number(trade.net_pnl||0)>=0?'positive':'negative'}}">${{tradeMoney(trade.net_pnl)}}</td></tr>`).join(''):'<tr><td colspan="8" class="muted">Nenhuma operação registrada.</td></tr>'}}).catch(error=>document.getElementById('trade-rows').innerHTML='<tr><td colspan="8" class="negative">'+escapeHtml(error.message)+'</td></tr>');
    </script>""", active_nav="trades")


def render_account_page(bots: list[BotCatalogItem], expected_account_id: str = "", expected_server: str = "") -> HTMLResponse:
    strategies = "".join(
        f'<a class="strategy-row" href="/bots/{escape(bot.id)}"><div><strong>{escape(bot.name)}</strong><p>{escape(bot.description)}</p></div><span>{escape(bot.symbol)} · {escape(bot.timeframe)}</span><small>Ativa</small></a>'
        for bot in bots
    ) or '<p class="muted">Nenhuma estratégia ativa.</p>'
    return _page("Live Core | Conta", f"""<main><header class="header"><div><p class="eyebrow">MetaTrader 5 · conta real</p><h1>Conta</h1><p class="muted">Dados financeiros e identidade da conta real conectada.</p></div><span id="connection" class="status waiting"><i></i>Aguardando conexão</span></header>
    <section id="identity-warning" class="warning" hidden></section>
    <section class="balance-grid"><article class="balance panel"><p class="muted">Saldo atual</p><strong id="balance">—</strong><small id="equity">Equity —</small></article><article class="balance panel"><p class="muted">Saldo inicial</p><strong id="initial-balance">—</strong><small id="initial-caption">Primeiro saldo recebido do terminal</small></article></section>
    <section class="profit-grid"><article class="panel"><p class="muted">Lucro flutuante</p><strong id="floating">—</strong><small>Posições abertas agora</small></article><article class="panel"><p class="muted">Realizado hoje</p><strong id="realized">—</strong><small id="profit-day">Dia da corretora</small></article></section>
    <section class="panel details"><h2>Identificação</h2><dl><div><dt>ID da conta</dt><dd id="account-id">—</dd></div><div><dt>Corretora</dt><dd id="broker">—</dd></div><div><dt>Servidor</dt><dd id="server">—</dd></div><div><dt>Tipo</dt><dd id="trade-mode">—</dd></div><div><dt>Alavancagem</dt><dd id="leverage">—</dd></div><div><dt>Margem livre</dt><dd id="margin-free">—</dd></div></dl></section>
    <section class="panel strategies"><div class="section-heading"><div><p class="eyebrow">Operação</p><h2>Estratégias ativas</h2></div><span>{len(bots)} estratégias</span></div><div class="strategy-list">{strategies}</div></section><p id="updated" class="muted">Buscando dados do terminal…</p></main><style>
    .eyebrow{{margin-bottom:7px;color:#b9b0ff;font-size:11px;font-weight:800;letter-spacing:.08em;text-transform:uppercase}}.status{{display:inline-flex;align-items:center;gap:9px;padding:9px 12px;border:1px solid #293342;border-radius:999px;color:var(--muted);font-size:12px;font-weight:800;text-transform:uppercase}}.status i{{width:9px;height:9px;border-radius:50%;background:#687386}}.status.online{{color:var(--green)}}.status.online i{{background:var(--green)}}.status.delayed{{color:var(--yellow)}}.status.delayed i{{background:var(--yellow)}}.status.offline{{color:var(--red)}}.status.offline i{{background:var(--red)}}.warning{{padding:14px 16px;margin-bottom:18px;border:1px solid rgba(246,198,103,.55);border-radius:9px;color:var(--yellow);background:rgba(246,198,103,.08)}}.balance-grid,.profit-grid{{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px;margin-bottom:16px}}.balance{{padding:25px}}.balance p{{margin-bottom:10px}}.balance strong{{display:block;font-size:46px;line-height:1.05;font-variant-numeric:tabular-nums}}.balance small,.profit-grid small{{display:block;margin-top:9px;color:var(--muted)}}.profit-grid article{{padding:21px}}.profit-grid strong{{font-size:28px}}.positive{{color:var(--green)}}.negative{{color:var(--red)}}.neutral{{color:var(--yellow)}}.details,.strategies{{padding:22px;margin-bottom:16px}}.details dl{{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:1px;margin:0;background:#292929}}.details dl div{{padding:16px;background:var(--panel)}}dt{{margin-bottom:7px;color:var(--muted);font-size:11px;text-transform:uppercase}}dd{{margin:0;font-weight:750}}.section-heading{{display:flex;align-items:flex-end;justify-content:space-between;gap:16px;margin-bottom:16px}}.section-heading h2{{margin:0}}.section-heading span{{color:var(--muted);font-size:12px}}.strategy-list{{display:grid;gap:8px}}.strategy-row{{display:grid;grid-template-columns:minmax(0,1fr) auto 58px;align-items:center;gap:14px;padding:13px 14px;border:1px solid #292929;border-radius:8px;color:var(--text);text-decoration:none;background:#0f0f0f}}.strategy-row p,.strategy-row span,.strategy-row small{{margin:4px 0 0;color:var(--muted);font-size:12px}}.strategy-row small{{color:var(--green);text-align:right}}@media(max-width:720px){{.balance-grid,.profit-grid,.details dl{{grid-template-columns:1fr}}.balance strong{{font-size:36px}}.strategy-row{{grid-template-columns:1fr auto}}.strategy-row span{{display:none}}}}
    </style><script>document.getElementById('account-id').textContent={expected_account_id!r}||'—';document.getElementById('server').textContent={expected_server!r}||'—';</script><script>
    const money=(value,currency)=>new Intl.NumberFormat('pt-BR',{{style:'currency',currency:currency||'USD'}}).format(Number(value||0));const tone=value=>Number(value)>0?'positive':Number(value)<0?'negative':'neutral';const put=(id,value)=>document.getElementById(id).textContent=value;function render(data){{const status=document.getElementById('connection');status.className='status '+data.status;status.innerHTML='<i></i>'+({{online:'Online',delayed:'Dados atrasados',offline:'Offline',waiting:'Aguardando conexão'}}[data.status]||data.status);const warning=document.getElementById('identity-warning');if(!data.available){{warning.hidden=false;warning.textContent='Nenhum dado recebido do terminal da conta real.';return}}const a=data.account,currency=a.currency||'USD';put('initial-balance',money(data.initial_balance,currency));put('balance',money(a.balance,currency));put('equity','Equity '+money(a.equity,currency));for(const [id,value] of [['floating',a.floating_profit],['realized',a.realized_profit_today]]){{const el=document.getElementById(id);el.textContent=value==null?'Aguardando EA atualizado':money(value,currency);el.className=value==null?'':tone(value)}}put('profit-day',a.profit_day?'Dia da corretora · '+new Date(a.profit_day+'T12:00:00Z').toLocaleDateString('pt-BR'):'Dia da corretora');put('account-id',a.login||'—');put('broker',a.broker||'—');put('server',a.server||'—');put('trade-mode',({{demo:'Demo',contest:'Concurso',real:'Real',unknown:'Desconhecida'}}[a.trade_mode]||a.trade_mode));put('leverage',a.leverage?'1:'+a.leverage:'—');put('margin-free',money(a.margin_free,currency));warning.hidden=data.identity_matches!==false;if(!warning.hidden)warning.textContent='A conta conectada não corresponde ao ID real configurado no ambiente.';put('updated','Última leitura: '+new Date(data.observed_at_utc).toLocaleString('pt-BR',{{timeZone:'UTC'}})+' UTC · há '+Math.round(data.age_seconds)+' s')}}async function refresh(){{try{{const response=await fetch('/api/account');const data=await response.json();if(!response.ok)throw Error(data.detail||'Falha ao consultar a conta.');render(data)}}catch(error){{put('updated',error.message)}}}}refresh();setInterval(refresh,10000);
    </script>""", active_nav="account")


def render_server_page() -> HTMLResponse:
    return _page("Live Core | Servidor", """<main><header class="header"><div><p class="eyebrow">Infraestrutura de execução</p><h1>Servidor</h1><p class="muted">Conexão do VPS responsável por executar o ZigZag Scalper próximo à Fusion Markets.</p></div><span id="server-state" class="server-state waiting">Aguardando configuração</span></header>
    <section class="connection-grid"><article class="panel connection-main"><div class="section-heading"><div><p class="eyebrow">FXVPS</p><h2>Dados da conexão</h2></div><span id="connection-badge">Não configurado</span></div><dl><div><dt>Provedor</dt><dd id="server-provider">—</dd></div><div><dt>Host ou IP</dt><dd id="server-host">—</dd></div><div><dt>Região</dt><dd id="server-region">—</dd></div><div><dt>Usuário SSH</dt><dd id="server-user">—</dd></div><div><dt>Porta SSH</dt><dd id="server-port">—</dd></div><div><dt>API remota</dt><dd id="server-api">—</dd></div></dl><p class="security-note">Senha e chave privada nunca são exibidas nem armazenadas nesta página. Use autenticação SSH por chave e mantenha o segredo fora do repositório.</p></article>
    <article class="panel workload"><p class="eyebrow">Carga operacional</p><h2>ZigZag Scalper</h2><p class="muted">O código da estratégia, o terminal MT5 e o serviço de decisão devem rodar juntos no VPS para evitar uma viagem de rede adicional antes da ordem.</p><ul><li><b>Ativo</b><span>XAUUSD · M5</span></li><li><b>Corretora</b><span>Fusion Markets</span></li><li><b>Resultados</b><span id="results-target">—</span></li></ul></article></section>
    <section class="panel flow"><div class="section-heading"><div><p class="eyebrow">Fluxo distribuído</p><h2>Execução e retorno dos dados</h2></div></div><div class="flow-track"><article><b>Fusion Markets</b><span>Ticks, preços e execução</span></article><i>↔</i><article><b>VPS FXVPS</b><span>MT5 + EA + ZigZag Scalper + API</span></article><i>→</i><article><b>Persistência central</b><span>Trades, candidatos, candles e telemetria</span></article><i>→</i><article><b>Painel Live Core</b><span>Consulta e baixa dos resultados</span></article></div><p class="flow-note">O caminho crítico da ordem fica no VPS. O retorno de resultados pode tolerar mais latência e deve ser idempotente para suportar quedas temporárias de rede.</p></section>
    <section class="panel checklist"><div class="section-heading"><div><p class="eyebrow">Antes da migração</p><h2>Checklist do servidor</h2></div></div><div class="check-grid"><p>□ Confirmar a região e medir a latência até o servidor da Fusion Markets.</p><p>□ Instalar MT5, EA, Python 3.12 e o serviço Live Core no mesmo VPS.</p><p>□ Configurar firewall, SSH por chave e acesso administrativo restrito.</p><p>□ Separar secrets, logs e persistência dos ambientes demo e real.</p><p>□ Validar sincronização e reconciliação de resultados após queda de rede.</p><p>□ Rodar em shadow/demo antes de habilitar qualquer decisão real.</p></div></section></main><style>
    .server-state{padding:7px 10px;border:1px solid #344155;border-radius:999px;color:var(--muted);font-size:10px;font-weight:800;letter-spacing:.06em;text-transform:uppercase}.server-state.configured{color:var(--green);border-color:rgba(65,211,146,.45)}.connection-grid{display:grid;grid-template-columns:minmax(0,1.6fr) minmax(280px,.8fr);gap:16px;margin-bottom:16px}.connection-main,.workload,.flow,.checklist{padding:22px}.section-heading{display:flex;align-items:flex-start;justify-content:space-between;gap:16px;margin-bottom:18px}.section-heading h2,.workload h2{margin:4px 0}.section-heading>span{padding:5px 8px;border-radius:999px;color:var(--muted);background:#151d28;font-size:11px}.connection-main dl{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:1px;margin:0;background:#263142}.connection-main dl div{padding:15px;background:var(--panel)}dt{margin-bottom:6px;color:var(--muted);font-size:10px;font-weight:800;text-transform:uppercase}dd{margin:0;overflow-wrap:anywhere;font-weight:700}.security-note,.flow-note{margin:16px 0 0;color:var(--muted);font-size:12px;line-height:1.55}.workload>p{line-height:1.55}.workload ul{display:grid;gap:1px;padding:0;margin:20px 0 0;background:#263142;list-style:none}.workload li{display:flex;justify-content:space-between;gap:12px;padding:13px;background:var(--panel);font-size:12px}.workload li span{color:var(--muted);text-align:right}.flow{margin-bottom:16px}.flow-track{display:grid;grid-template-columns:repeat(7,auto);align-items:center;gap:10px}.flow-track article{min-height:94px;display:flex;flex-direction:column;justify-content:center;padding:15px;border:1px solid #263142;border-radius:8px;background:#0a0e14}.flow-track span{margin-top:6px;color:var(--muted);font-size:11px;line-height:1.4}.flow-track i{color:#8b7cff;font-style:normal;font-size:20px}.check-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.check-grid p{margin:0;padding:13px;border:1px solid #263142;border-radius:8px;color:var(--muted);font-size:12px;line-height:1.45}@media(max-width:900px){.connection-grid{grid-template-columns:1fr}.flow-track{grid-template-columns:1fr}.flow-track i{text-align:center;transform:rotate(90deg)}}@media(max-width:620px){.connection-main dl,.check-grid{grid-template-columns:1fr}}
    </style><script>
    const setServerValue=(id,value)=>document.getElementById(id).textContent=value||'Não configurado';fetch('/config').then(async response=>{{const data=await response.json();if(!response.ok)throw Error(data.detail||'Falha ao carregar a configuração.');setServerValue('server-provider',data.execution_server_provider);setServerValue('server-host',data.execution_server_host);setServerValue('server-region',data.execution_server_region);setServerValue('server-user',data.execution_server_ssh_user);setServerValue('server-port',String(data.execution_server_ssh_port||''));setServerValue('server-api',data.execution_server_api_url);setServerValue('results-target',data.execution_results_target);const configured=Boolean(data.execution_server_host&&data.execution_server_region&&data.execution_server_ssh_user&&data.execution_server_api_url);const state=document.getElementById('server-state');state.textContent=configured?'Conexão configurada':'Aguardando configuração';state.classList.toggle('configured',configured);document.getElementById('connection-badge').textContent=configured?'Configurado':'Não configurado'}}).catch(error=>document.getElementById('server-state').textContent=error.message);
    </script>""", active_nav="server")


def _render_security_page_legacy() -> HTMLResponse:
    return _page("Live Core | Segurança Live Core", """<main><header class="header"><div><h1>Segurança Live Core</h1><p class="muted">Proteções e controles que governam a execução real.</p></div><span class="read-only">CONTROLE DE RUNTIME</span></header>
    <section class="settings-section" id="execution-settings"><div class="settings-heading"><p class="eyebrow">Configurações de segurança</p><h2>Configurações de execução</h2><p class="muted">As alterações valem imediatamente neste processo. Ao reiniciar, o serviço volta aos valores definidos no ambiente.</p></div><div class="setting-list">
    <article class="panel setting"><div><code>DAYTRADE_ENABLE_LIVE_DECISIONS</code><h3>Permitir decisões reais</h3><p>Libera a API para considerar sinais executáveis. Sozinha, esta opção não envia ordens: o canário e todas as demais proteções também precisam estar válidos.</p></div><button id="enable-live-decisions" class="setting-toggle" type="button" role="switch" aria-checked="false" disabled><i></i><b>Carregando</b></button></article>
    <article class="panel setting"><div><code>LIVE_CANARY_ARMED</code><h3>Armar canário do servidor</h3><p>É o kill switch remoto. Desarmado, converte decisões executáveis em <code>hold</code>; armado, ainda exige conta, estratégia, persistência e limites válidos.</p></div><button id="live-canary-armed" class="setting-toggle" type="button" role="switch" aria-checked="false" disabled><i></i><b>Carregando</b></button></article>
    </div><p id="settings-feedback" class="settings-feedback muted" role="status" aria-live="polite">As duas opções são independentes.</p></section><section class="security-hero panel"><div><p class="eyebrow">Estado do canário</p><h2 id="security-state">Verificando...</h2><p class="muted" id="security-detail">Carregando as duas travas independentes.</p></div><span class="security-dot" id="security-dot"></span></section><section class="gate-list" id="gate-list"><article class="panel"><p class="muted">Carregando proteções...</p></article></section><section class="panel promoted"><div><p class="eyebrow">Registro de promoção</p><h2>Bundles importados</h2></div><strong id="promoted-count">—</strong></section></main><style>
    .read-only{padding:7px 10px;border:1px solid #344155;border-radius:999px;color:var(--muted);font-size:10px;font-weight:800;letter-spacing:.08em}.security-hero{display:flex;align-items:center;justify-content:space-between;padding:23px;margin-bottom:24px}.security-hero h2{margin:5px 0 7px}.security-dot{width:15px;height:15px;border-radius:50%;background:var(--yellow);box-shadow:0 0 0 7px rgba(246,198,103,.1)}.security-dot.protected{background:var(--green);box-shadow:0 0 0 7px rgba(65,211,146,.1)}.settings-section{margin-bottom:24px}.settings-heading{margin-bottom:14px}.settings-heading h2{margin:4px 0 7px}.setting-list{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.setting{display:flex;align-items:center;justify-content:space-between;gap:24px;padding:22px}.setting>div{max-width:570px}.setting code{color:#b9b0ff;font-size:11px}.setting h3{margin:8px 0}.setting p{margin:0;color:var(--muted);font-size:13px;line-height:1.55}.setting p code{color:#dce4f1}.setting-toggle{min-width:126px;display:flex;align-items:center;gap:9px;padding:9px 12px;border:1px solid #344155;border-radius:999px;color:#c4cedd;background:#151d28;font-size:11px;font-weight:800}.setting-toggle i{width:10px;height:10px;border-radius:50%;background:var(--red)}.setting-toggle[aria-checked="true"]{color:var(--yellow);border-color:rgba(246,198,103,.55);background:rgba(246,198,103,.08)}.setting-toggle[aria-checked="true"] i{background:var(--yellow)}.setting-toggle:disabled{cursor:wait;opacity:.55}.settings-feedback{min-height:20px;margin:10px 3px 0;font-size:12px}.settings-feedback.error{color:var(--red)}.gate-list{display:grid;grid-template-columns:repeat(2,1fr);gap:12px;margin-bottom:18px}.gate{display:flex;align-items:center;justify-content:space-between;gap:18px;padding:17px}.gate div{display:grid;gap:5px}.gate small{color:var(--muted)}.gate b{padding:6px 9px;border-radius:999px;background:#151d28;color:#aeb9ca;font-size:11px}.gate b.safe{color:var(--green);background:rgba(65,211,146,.08)}.promoted{display:flex;justify-content:space-between;align-items:center;padding:20px}.promoted h2{margin:0}.promoted>strong{font-size:30px}@media(max-width:850px){.setting-list,.gate-list{grid-template-columns:1fr}}@media(max-width:560px){.setting{align-items:flex-start;flex-direction:column}.setting-toggle{width:100%;justify-content:center}}
    </style><script>
    let securityConfig=null,securityReady=null,securityCanary=null;const controls={{enable_live_decisions:document.getElementById('enable-live-decisions'),live_canary_armed:document.getElementById('live-canary-armed')}};
    function renderControl(key,value){{const button=controls[key];button.disabled=false;button.setAttribute('aria-checked',String(Boolean(value)));button.querySelector('b').textContent=value?(key==='live_canary_armed'?'Armado':'Habilitadas'):(key==='live_canary_armed'?'Desarmado':'Desabilitadas')}}
    function renderSecurity(config,ready,canary){{securityConfig=config;const protectedMode=!config.enable_live_decisions||!config.live_canary_armed;document.getElementById('security-state').textContent=protectedMode?'Execução real bloqueada':'Canário armado';document.getElementById('security-detail').textContent=protectedMode?'As duas chaves independentes não autorizam uma ordem real.':'Monitoramento humano obrigatório enquanto o canário estiver armado.';document.getElementById('security-dot').classList.toggle('protected',protectedMode);renderControl('enable_live_decisions',config.enable_live_decisions);renderControl('live_canary_armed',config.live_canary_armed);const gates=[['Conta MT5 permitida',config.live_canary_account_login||'Não configurada',config.live_canary_account_login===0],['Lote máximo',Number(config.live_canary_max_lot).toFixed(2)+' lote',config.live_canary_max_lot<=0.01],['Spread máximo',Number(config.live_canary_max_spread_points).toFixed(1)+' pontos',true],['Persistência exigida',config.results_store,config.results_store==='SUPABASE'],['Estratégia elegível',config.live_canary_bot_id||'Não configurada',!config.live_canary_bot_id],['Aplicação',ready.status,ready.status==='ready'],['Canário real',canary.status,!canary.ready]];document.getElementById('gate-list').innerHTML=gates.map(gate=>`<article class="panel gate"><div><strong>${{escapeHtml(String(gate[0]))}}</strong><small>Proteção fail-closed</small></div><b class="${{gate[2]?'safe':''}}">${{escapeHtml(String(gate[1]))}}</b></article>`).join('')}}
    async function updateSetting(key){{if(!securityConfig)return;const next=!securityConfig[key];let password=null;if(next){{if(!confirm('Ativar esta trava no processo atual? A execução real só será possível quando ambas estiverem ativas e todas as proteções passarem.'))return;password=prompt('Confirme sua senha do painel para ativar esta trava:');if(password===null)return}}const feedback=document.getElementById('settings-feedback');feedback.className='settings-feedback muted';feedback.textContent='Aplicando alteração...';Object.values(controls).forEach(button=>button.disabled=true);try{{const payload={{enable_live_decisions:securityConfig.enable_live_decisions,live_canary_armed:securityConfig.live_canary_armed,password}};payload[key]=next;const response=await fetch('/api/security-settings',{{method:'PUT',headers:{{'Content-Type':'application/json'}},body:JSON.stringify(payload)}});const data=await response.json();if(!response.ok){{const detail=typeof data.detail==='string'?data.detail:data.detail?.message;throw Error(detail||'Não foi possível alterar a configuração.')}}securityConfig={{...securityConfig,...data}};const canaryResponse=await fetch('/api/canary-readiness');securityCanary=await canaryResponse.json();renderSecurity(securityConfig,securityReady,securityCanary);feedback.textContent='Configuração aplicada e registrada na auditoria. Reiniciar o serviço restaura os valores do ambiente.'}}catch(error){{feedback.className='settings-feedback error';feedback.textContent=error.message;Object.values(controls).forEach(button=>button.disabled=false)}}}}
    Object.entries(controls).forEach(([key,button])=>button.addEventListener('click',()=>updateSetting(key)));
    Promise.all([fetch('/config'),fetch('/api/promoted-strategies'),fetch('/ready'),fetch('/api/canary-readiness')]).then(async responses=>{{const [config,promoted,ready,canary]=await Promise.all(responses.map(async response=>{{const data=await response.json();if(!response.ok)throw Error(data.detail||data.status);return data}}));securityReady=ready;securityCanary=canary;renderSecurity(config,ready,canary);document.getElementById('promoted-count').textContent=promoted.count}}).catch(error=>document.getElementById('security-state').textContent=error.message);
    </script>""", active_nav="security")


